import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(0)
        return

    n = int(data[0])
    k = int(data[1])

    if n == 0:
        print(0)
        return

    arr = list(map(int, data[2:2+n]))

    if k < 0:
        k = -k

    arr.sort()
    count = 0
    left = 0
    right = 0

    while right < n:
        diff = arr[right] - arr[left]
        if diff < k:
            right += 1
        elif diff > k:
            left += 1
        else:
            count += 1
            right += 1

    print(count)

if __name__ == "__main__":
    main()
